def compute(vars):
    professional_services_revenue = vars["v1"]
    total_revenue = vars["v2"]
    if total_revenue == 0:
        return None
    value = professional_services_revenue / total_revenue * 100
    return {
        "value": value,
        "trace": {
            "professional_services_revenue": professional_services_revenue,
            "total_revenue": total_revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
